        visualizationHintAr: 'تخيّل الفاعل ممثلاً غادر المسرح فجأة (حُذف). المخرج (القاعدة النحوية) يدفع المفعول به إلى مقدمة المسرح ليأخذ مكانه ويصبح "نائب الفاعل" — يرتدي نفس "لباس" الفاعل (الرفع).',
