        visualizationHintAr: 'تخيّل الفعل المجرد كبيت من طابق واحد (3 أحرف أصلية). الفعل المزيد يضيف طوابق فوقه (حرف، حرفين، أو ثلاثة). اسم الفاعل واسم المفعول كأنهما "بطاقتا هوية" تُصاغان من نفس البيت: واحدة لمن سكن فيه (الفاعل) وواحدة لما حدث بداخله (المفعول).',
