    summaryAr: `تُقَيَّمُ الوَضْعِيَّةُ الإِدْمَاجِيَّةُ فِي التَّقْيِيمِ الرَّسْمِيِّ وَفْقَ ثَلَاثَةِ مَعَايِيرَ أَسَاسِيَّةٍ: مَلَاءَمَةُ المُنْتُوجِ لِلتَّعْلِيمَةِ، اِنْسِجَامُ أَفْكَارِ النَّصِّ وَتَسَلْسُلُهَا، وَسَلَامَةُ اللُّغَةِ (نَحْواً وَصَرْفاً وَإِمْلَاءً)، وَيَتَعَلَّمُ التِّلْمِيذُ تَوْظِيفَهَا لِمُرَاجَعَةِ نَصِّهِ ذَاتِيّاً.`,
