    sourceNoteAr: 'محتوى تربوي تكميلي (أصلي) لم تتم مقارنته بمصدر ثانوي بعد. يُنصح بمراجعته مع معلم(ة) القسم قبل اعتماده كمرجع وحيد لمراجعة الامتحان.',
